194	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheet.getToday())) {
195	            throw new ResponseStatusException(HttpStatus.CONFLICT,
196	                    "A claim deferred until " + claim.getDeferredUntil() + " cannot be settled before then");
197	        }
198	        if (next == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
199	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The user who opened a claim cannot settle it");
200	        }
201	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
202	        BigDecimal due = dueNow(sheet, claim, person);
203	        if (next == ClaimStatus.SETTLED) {
204	            refuseUnproven(sheet, claim, due);
205	        } else if (next == ClaimStatus.OPEN) {
206	            refuseUnnoted(sheet, claim, due);
207	        }
208	        if (next == ClaimStatus.SETTLED && overClerkLimit(sheet, user, due)) {
209	            next = ClaimStatus.PENDING;
210	        }
211	        Rollup.Figures before = rollup.of(sheetId);
212	        String number = claim.getNumber();
213	        claim.setStatus(next);
214	        if (next == ClaimStatus.OPEN) {
215	            number = nextNumber(sheet, claim.getDate());
216	            claim.setNumber(number);
217	            claim.setOpenedBy(user);
218	        } else if (next == ClaimStatus.SETTLED) {
219	            claim.setSettledDue(due);
220	        }
221	        claim.logStatus(user, sheet.getToday(), shownDue(sheet, claim, person));
222	        Claim changed = claims.saveAndFlush(claim);
223	        String event = switch (next) {
224	            case OPEN -> "CLAIM_OPENED";
225	            case PENDING -> "CLAIM_PENDING";
226	            case SETTLED -> "CLAIM_SETTLED";
227	            case VOID -> "CLAIM_VOIDED";
228	            case DRAFT -> throw new IllegalStateException();
229	        };
230	        String line = entry(event, user, person, changed, number);
231	        if (next == ClaimStatus.SETTLED) {
232	            line += " due=" + dueText(changed);
233	        } else if (voidsSettled) {
234	            line += " reversed=" + dueText(changed);
235	        }
236	        audit.recordChangeOnCommit(sheetId, user, line);
237	        if (next == ClaimStatus.SETTLED) {
238	            watches.notifyWatchers(sheetId, user, person, number);
239	        }
240	        rollup.recordChanges(sheetId, user, before);
241	        return changed;
242	    }
