272	     *  period gives it the next number of its new period's sequence (its old number is never given again). Refused
273	     *  for anyone but a steward, a claim in any other status, a claim dated inside a closed period, a new date inside
274	     *  one and a new date after its person retired. */
275	    @Transactional
276	    public Claim redate(String sheetId, String user, long id, LocalDate date) {
277	        sheets.load(sheetId, user);
278	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
279	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
280	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
281	        if (!Role.STEWARD.equals(roles.roleOf(sheetId, user))) {
282	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward re-dates a claim");
283	        }
284	        if (!claim.getStatus().isOpen()) {
285	            throw new ResponseStatusException(HttpStatus.CONFLICT,
