457	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet"));
458	        if (!sheet.allows("reassign", roles.roleOf(sheetId, user))) {
459	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not reassign a claim");
460	        }
