486	    /** Split an amount (more than 0.00 and less than its amount) off an OPEN claim: it keeps the rest and loses any
487	     *  figure a statement bound it to; a new OPEN claim of the same person with the amount split off, the same date
488	     *  and note, the next number, opened by this user, a due-by fixed now from the terms in force on the date and
489	     *  naming the original as the claim it was split from, is listed as the person's newest. Refused for a claim
490	     *  that is not OPEN or is deferred, one dated inside a closed period, an amount out of range, and a role the
491	     *  permission matrix does not allow to open a claim. */
492	    @Transactional
493	    public Split split(String sheetId, String user, long id, BigDecimal amount) {
494	        sheets.load(sheetId, user);
495	        Sheet sheet = sheetStore.findLockedById(sheetId).orElseThrow();
496	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
497	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim on this sheet"));
498	        refuseIfClosed(sheetId, claim.getDate());
499	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheet.getToday())) {
500	            throw new ResponseStatusException(HttpStatus.CONFLICT,
501	                    "A " + claim.getStatus() + " claim cannot be split; only an OPEN one not deferred can");
502	        }
503	        if (!sheet.allows("open", roles.roleOf(sheetId, user))) {
504	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not open a claim");
505	        }
506	        BigDecimal part = scaled(amount);
507	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
508	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
509	                    "The amount split off must be more than 0.00 and less than " + claim.getAmount().toPlainString());
510	        }
511	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId).orElseThrow();
512	        Rollup.Figures before = rollup.of(sheetId);
513	        claim.setAmount(claim.getAmount().subtract(part));
514	        claim.unbind();
515	        Claim original = claims.saveAndFlush(claim);
516	        LocalDate date = original.getDate();
517	        LocalDate dueBy = date.plusDays(termsOf(sheet, person, date));
518	        Claim added = new Claim(sheetId, person.getId(), part, date, dueBy, original.getNote(), null,
519	                claims.lastListed(sheetId) + 1);
520	        added.openAsSplit(nextNumber(sheet, date), user, original.getNumber());
521	        added.logStatus(user, sheet.getToday(), shownDue(sheet, added, person));
522	        added = claims.saveAndFlush(added);
523	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_SPLIT", user, person, original, original.getNumber())
524	                + " into=" + added.getNumber());
525	        audit.recordChangeOnCommit(sheetId, user, entry("CLAIM_OPENED", user, person, added, added.getNumber()));
526	        rollup.recordChanges(sheetId, user, before);
527	        return new Split(original, added);
528	    }
