546	    /** The due a claim would be settled at now: its bound figure, else its live one, with the late charge it has
547	     *  gained on top, raised to the floor in force on its date; null when it has no figure. */
548	    private BigDecimal dueNow(Sheet sheet, Claim claim, Person person) {
549	        BigDecimal live = liveNow(sheet, claim, person);
550	        // Settling freezes the claim's figure (its bound one, else its live one) with the late charge it has gained,
551	        // raised to the floor.
552	        BigDecimal figure = claim.isBound() ? claim.getBoundDue() : live;
553	        return figure == null ? null : floored(claim, figure.add(lateCharge(claim, figure, sheet)), sheet);
554	    }
