556	    /** A claim's live figure as rates and grades are now, bound by no statement; null when its grade has
557	     *  no rate in force on its date. */
558	    private BigDecimal liveNow(Sheet sheet, Claim claim, Person person) {
559	        String sheetId = sheet.getId();
560	        return Rate.inForceOn(rates.findBySheetIdAndGrade(sheetId, person.gradeOn(claim.getDate())), claim.getDate())
561	                .map(Rate::getRate)
562	                .map(rate -> liveFigure(claim, rate, sheet.roundingFor(roundingDate(claim,
563	                        claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, claim.getPersonId())))))
564	                .orElse(null);
565	    }
