576	    /** The next number for a claim dated on this day, opened now: within its period (<period name>-<n>, or X-<n>
577	     *  in no period) while the sheet's period numbering is on by its today, else the sheet's next number. */
578	    private String nextNumber(Sheet sheet, LocalDate date) {
579	        if (!sheet.numbersPerPeriod()) {
580	            return String.valueOf(sheet.nextClaimNumber());
581	        }
582	        String prefix = prefixOn(sheet, date);
583	        ClaimSequence sequence = sequences.findBySheetIdAndPrefix(sheet.getId(), prefix)
584	                .orElseGet(() -> new ClaimSequence(sheet.getId(), prefix));
585	        String number = sequence.next();
586	        sequences.save(sequence);
587	        return number;
588	    }
