590	    /** The prefix of the numbers given within the period a day is in: its name, or X in no period. */
591	    private String prefixOn(Sheet sheet, LocalDate date) {
592	        return periods.findBySheetIdOrderByFromDateAsc(sheet.getId()).stream()
593	                .filter(p -> p.contains(date)).map(Period::getName).findFirst().orElse(NO_PERIOD);
594	    }
