596	    /** Refuse to settle or approve a claim with no proofs whose due is above the proof threshold in force on its
597	     *  date (a claim with no due, or on a sheet with no threshold then, needs none). */
598	    private static void refuseUnproven(Sheet sheet, Claim claim, BigDecimal due) {
599	        BigDecimal threshold = sheet.proofThresholdOn(claim.getDate());
600	        if (claim.getProofs() == 0 && threshold != null && due != null && due.compareTo(threshold) > 0) {
601	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
602	                    "A claim whose due is above the proof threshold of " + threshold + " needs a proof first");
603	        }
604	    }
