606	    /** Refuse to open a claim with an empty note whose due is above the note threshold in force on its date (a claim
607	     *  with no due, or on a sheet with no threshold then, needs none). */
608	    private static void refuseUnnoted(Sheet sheet, Claim claim, BigDecimal due) {
609	        BigDecimal threshold = sheet.noteThresholdOn(claim.getDate());
610	        if ((claim.getNote() == null || claim.getNote().isBlank()) && threshold != null && due != null
611	                && due.compareTo(threshold) > 0) {
612	            throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,
613	                    "A claim whose due is above the note threshold of " + threshold + " needs a note first");
614	        }
615	    }
