617	    /** Whether a settle by this user must wait for a steward: they are a clerk and the due is above the sheet's
618	     *  clerk limit (a claim with no due is within any limit). */
619	    private boolean overClerkLimit(Sheet sheet, String user, BigDecimal due) {
620	        BigDecimal limit = sheet.getClerkLimit();
621	        if (limit == null || due == null || due.compareTo(limit) <= 0) {
622	            return false;
623	        }
624	        return !Role.STEWARD.equals(roles.roleOf(sheet.getId(), user));
625	    }
626	
627	    /** Refuse to void a SETTLED claim for anyone but a steward, and on a sheet's today more than
628	     *  {@value #SETTLED_VOID_DAYS} days after (or before) the day its log records it settled. */
629	    private void refuseSettledVoid(Sheet sheet, String user, Claim claim) {
630	        if (!Role.STEWARD.equals(roles.roleOf(sheet.getId(), user))) {
631	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward may void a SETTLED claim");
632	        }
633	        LocalDate settled = claim.settledOn();
634	        LocalDate today = sheet.getToday();
635	        if (settled == null || today.isBefore(settled) || today.isAfter(settled.plusDays(SETTLED_VOID_DAYS))) {
636	            throw new ResponseStatusException(HttpStatus.CONFLICT,
637	                    "A SETTLED claim can be voided only within " + SETTLED_VOID_DAYS + " days of its settlement");
638	        }
639	    }
640	
641	    /** Refuse a correction (a negative amount) that does not name, by number, a SETTLED claim of the same person,
642	     *  and a claim that is not a correction but names one. */
643	    private void refuseUnlessCorrects(String sheetId, long personId, BigDecimal amount, String corrects) {
644	        if (amount.signum() >= 0) {
645	            if (corrects != null) {
646	                throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
647	                        "Only a correction (a negative amount) names a claim it corrects");
648	            }
649	            return;
650	        }
651	        boolean settled = corrects != null && claims.findBySheetIdAndPersonIdOrderByListedDescIdDesc(sheetId, personId).stream()
652	                .anyMatch(c -> corrects.equals(c.getNumber()) && c.getStatus() == ClaimStatus.SETTLED);
653	        if (!settled) {
654	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
655	                    "A correction must name the number of a SETTLED claim of the same person");
656	        }
657	    }
658	
659	    /** Refuse a change to a claim dated inside a closed period of the sheet. */
660	    private void refuseIfClosed(String sheetId, LocalDate date) {
661	        if (periods.existsBySheetIdAndClosedTrueAndFromDateLessThanEqualAndToDateGreaterThanEqual(sheetId, date, date)) {
662	            throw new ResponseStatusException(HttpStatus.LOCKED, "That claim's date is inside a closed period");
663	        }
664	    }
665	
666	    /** Refuse a claim dated after its person's retirement date. */
667	    private static void refuseIfRetired(Person person, LocalDate date) {
668	        if (person.refusesClaimOn(date)) {
669	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
670	                    "That claim is dated after " + person.getName() + " retired");
671	        }
672	    }
673	
674	    /** An audit line about a claim; one with a number (a void claim keeps the one it had) ends with it. */
675	    private static String entry(String event, String user, Person person, Claim claim, String number) {
676	        return event + " sheet=" + claim.getSheetId() + " by=" + user + " person=" + person.getName()
677	                + " amount=" + claim.getAmount().toPlainString() + " date=" + claim.getDate()
678	                + (number == null ? "" : " number=" + number);
679	    }
680	
681	    /** The due on an amount at a rate (a percent): amount × rate / 100, rounded to the cent as the claim it is on
682	     *  rounds (half up rounds a negative half away from zero, as its opposite would). */
683	    public static BigDecimal dueOn(BigDecimal amount, BigDecimal rate, RoundingMode rounding) {
684	        return amount.multiply(rate).movePointLeft(2).setScale(2, rounding);
685	    }
686	
687	    /** The date that decides how a claim's live figures round: its own date, or for a correction the date of the
688	     *  claim of the same person it corrects. */
689	    public static LocalDate roundingDate(Claim claim, Collection<Claim> sheetClaims) {
690	        if (claim.getCorrects() == null) {
691	            return claim.getDate();
692	        }
693	        return sheetClaims.stream()
694	                .filter(c -> c.getPersonId().equals(claim.getPersonId()) && claim.getCorrects().equals(c.getNumber()))
695	                .map(Claim::getDate).findFirst().orElse(claim.getDate());
696	    }
697	
698	    /** The late charge an OPEN or PENDING claim, not deferred, has gained on its figure by the sheet's today: for each
699	     *  full 30 days past the day it is due by, the late percent in force on that boundary date (its due-by plus 30, 60,
700	     *  90 ... days) of the figure, rounded as the claim rounds, added up; 0.00 when not overdue, it has no figure, or
701	     *  it is a correction. */
702	    public static BigDecimal lateCharge(Claim claim, BigDecimal figure, Sheet sheet) {
703	        BigDecimal none = BigDecimal.ZERO.setScale(2);
704	        if (!claim.getStatus().isOpen() || claim.isDeferredOn(sheet.getToday())) {
705	            return none;
706	        }
707	        return lateChargeAsOpen(claim, figure, sheet);
708	    }
709	
710	    /** The late charge a claim would have gained on its figure by the sheet's today were it still open. */
711	    private static BigDecimal lateChargeAsOpen(Claim claim, BigDecimal figure, Sheet sheet) {
712	        BigDecimal none = BigDecimal.ZERO.setScale(2);
713	        if (figure == null || claim.isCorrection()) {
714	            return none;
715	        }
716	        long periods = ChronoUnit.DAYS.between(claim.getDueBy(), sheet.getToday()) / 30;
717	        RoundingMode rounding = sheet.roundingFor(claim.getDate());
718	        BigDecimal charge = none;
719	        for (long k = 1; k <= periods; k++) {
720	            charge = charge.add(dueOn(figure, sheet.latePctOn(claim.getDueBy().plusDays(30 * k)), rounding));
721	        }
722	        return charge;
723	    }
724	
725	    /** A claim's live figure at a rate: its due on its amount, rounded as the claim rounds. The floor is not applied
726	     *  to it: it is applied last, to the figure with its late charge (see {@link #floored(Claim, BigDecimal, Sheet)}). */
727	    public static BigDecimal liveFigure(Claim claim, BigDecimal rate, RoundingMode rounding) {
728	        return dueOn(claim.getAmount(), rate, rounding);
729	    }
730	
731	    /** A claim's due (its figure with its late charge) raised to the floor in force on its date, unless it is a
732	     *  correction. */
733	    public static BigDecimal floored(Claim claim, BigDecimal due, Sheet sheet) {
734	        return due == null || claim.isCorrection() || sheet == null ? due : floored(due, sheet.floorOn(claim.getDate()));
735	    }
736	
737	    /** A live due raised to the sheet's floor when it is below it. */
738	    public static BigDecimal floored(BigDecimal due, BigDecimal floor) {
739	        return floor != null && due.compareTo(floor) < 0 ? floor : due;
740	    }
741	
742	    /** The terms in days a claim of the person dated {@code date} is due by: the person's own, else their grade's
743	     *  in force then, else the sheet's then. */
744	    private static int termsOf(Sheet sheet, Person person, LocalDate date) {
745	        return person.getTerms() != null ? person.getTerms() : sheet.termsFor(person.gradeOn(date), date);
746	    }
747	
748	    private static BigDecimal scaled(BigDecimal amount) {
749	        return amount.setScale(2, RoundingMode.UNNECESSARY);
750	    }
751	
752	    private static String noteOf(String note) {
753	        return note == null ? "" : note.trim();
754	    }
755	}
